# HLLSet core for Packet Tracer SBC Python.
# PT Python runs on a JavaScript engine: integers are doubles (exact only up to 2^53)
# and bitwise ops are 32-bit. So every 64-bit value is 4 limbs of 16 bits,
# little-endian: [bits 0-15, 16-31, 32-47, 48-63]. Bitwise ops only touch values < 2^16,
# products of two limbs stay < 2^32 (exact in a double) and are split with % and //.
# Bit-exact with hllset-contracts (ewm-state-machine):
# h = murmur3_x64_128(bytes, seed as u32).low64, reg = h & 0x3FF, tz = min(ctz(h >> 10), 31),
# bit = reg * 32 + tz.

L16 = 65536
C1 = [0x53d5, 0x1142, 0x7b91, 0x87c3]   # 0x87c37b91114253d5
C2 = [0x937f, 0x2745, 0xad43, 0x4cf5]   # 0x4cf5ad432745937f
F1 = [0x8ccd, 0xed55, 0xafd7, 0xff51]   # 0xff51afd7ed558ccd
F2 = [0xec53, 0x1a85, 0xb9fe, 0xc4ce]   # 0xc4ceb9fe1a85ec53
A1 = [0xe729, 0x52dc, 0, 0]             # 0x52dce729
A2 = [0x5ab5, 0x3849, 0, 0]             # 0x38495ab5
FIVE = [5, 0, 0, 0]


def small(n):
    # non-negative int < 2^48 -> limbs (arithmetic only)
    r = []
    for i in range(4):
        q = n // L16
        r.append(n - q * L16)
        n = q
    return r


def add(a, b):
    r = [0, 0, 0, 0]
    c = 0
    for i in range(4):
        s = a[i] + b[i] + c
        c = s // L16
        r[i] = s - c * L16
    return r


def mul(a, b):
    # (a * b) mod 2^64
    acc = [0, 0, 0, 0]
    for i in range(4):
        for j in range(4 - i):
            acc[i + j] = acc[i + j] + a[i] * b[j]
    r = [0, 0, 0, 0]
    c = 0
    for k in range(4):
        s = acc[k] + c
        c = s // L16
        r[k] = s - c * L16
    return r


def xor(a, b):
    return [a[0] ^ b[0], a[1] ^ b[1], a[2] ^ b[2], a[3] ^ b[3]]


def rotl(x, r):
    q = r // 16
    s = r - q * 16
    y = [x[(i - q + 4) % 4] for i in range(4)]
    if s == 0:
        return y
    return [((y[i] << s) & 0xFFFF) | (y[(i + 3) % 4] >> (16 - s)) for i in range(4)]


def shr(x, r):
    q = r // 16
    s = r - q * 16
    y = [0, 0, 0, 0]
    for i in range(4):
        if i + q < 4:
            y[i] = x[i + q]
    if s == 0:
        return y
    out = []
    for i in range(4):
        hi = y[i + 1] if i < 3 else 0
        out.append((y[i] >> s) | ((hi << (16 - s)) & 0xFFFF))
    return out


def fmix(k):
    k = xor(k, shr(k, 33))
    k = mul(k, F1)
    k = xor(k, shr(k, 33))
    k = mul(k, F2)
    k = xor(k, shr(k, 33))
    return k


def utf8(s):
    out = []
    for ch in s:
        c = ord(ch)
        if c < 0x80:
            out.append(c)
        elif c < 0x800:
            out.append(0xC0 | (c >> 6))
            out.append(0x80 | (c & 0x3F))
        elif c < 0x10000:
            out.append(0xE0 | (c >> 12))
            out.append(0x80 | ((c >> 6) & 0x3F))
            out.append(0x80 | (c & 0x3F))
        else:
            out.append(0xF0 | (c >> 18))
            out.append(0x80 | ((c >> 12) & 0x3F))
            out.append(0x80 | ((c >> 6) & 0x3F))
            out.append(0x80 | (c & 0x3F))
    return out


def word(d, i, n):
    # n (<= 8) little-endian bytes starting at d[i] -> limbs
    r = [0, 0, 0, 0]
    for j in range(n):
        r[j // 2] = r[j // 2] | (d[i + j] << (8 * (j % 2)))
    return r


def murmur64(text, seed):
    return murmur64_bytes(utf8(text), seed)


def murmur64_bytes(d, seed):
    # d = list of byte values 0..255
    n = len(d)
    s32 = seed % 4294967296
    h1 = small(s32)
    h2 = small(s32)
    nb = n // 16
    for b in range(nb):
        k1 = word(d, b * 16, 8)
        k2 = word(d, b * 16 + 8, 8)
        k1 = mul(rotl(mul(k1, C1), 31), C2)
        h1 = xor(h1, k1)
        h1 = add(mul(add(rotl(h1, 27), h2), FIVE), A1)
        k2 = mul(rotl(mul(k2, C2), 33), C1)
        h2 = xor(h2, k2)
        h2 = add(mul(add(rotl(h2, 31), h1), FIVE), A2)
    t = nb * 16
    rest = n - t
    if rest > 8:
        k2 = word(d, t + 8, rest - 8)
        h2 = xor(h2, mul(rotl(mul(k2, C2), 33), C1))
    if rest > 0:
        k1 = word(d, t, min(rest, 8))
        h1 = xor(h1, mul(rotl(mul(k1, C1), 31), C2))
    ln = small(n)
    h1 = xor(h1, ln)
    h2 = xor(h2, ln)
    h1 = add(h1, h2)
    h2 = add(h2, h1)
    h1 = fmix(h1)
    h2 = fmix(h2)
    return add(h1, h2)


def hex64(x):
    digits = "0123456789abcdef"
    s = ""
    for i in range(3, -1, -1):
        v = x[i]
        for k in (12, 8, 4, 0):
            s = s + digits[(v >> k) & 15]
    return "0x" + s


def ctz(x):
    for i in range(4):
        if x[i] != 0:
            v = x[i]
            c = 0
            while (v & 1) == 0:
                v = v >> 1
                c = c + 1
            return i * 16 + c
    return 64


def position_of(h):
    # hllset-contracts::hash_to_position: reg = h & 1023, tz = min(ctz(h >> 10), 31)
    # (h >> 10 == 0 gives ctz = 64 -> 31, the saturated convention of Rust)
    reg = h[0] & 0x3FF
    tz = ctz(shr(h, 10))
    if tz > 31:
        tz = 31
    return reg, tz


def position(text, seed):
    return position_of(murmur64(text, seed))


def bit_of_bytes(d, seed):
    # BitAddress::of_token_seeded(bytes, seed).bit() = reg * 32 + tz
    reg, tz = position_of(murmur64_bytes(d, seed))
    return reg * 32 + tz

# ---------------- common: SHA-1, line protocol over PT tcp ----------------
# Wire format: one message per line, fields separated by "|":  <rid>|<CMD>|<arg>|...
# rid = request id; replies reuse the rid of the request.
# Handshake: client sends "0|HELLO|<name>" until it gets "0|WELCOME|<name>".

TICK = [0]          # main-loop tick counter (0.5 s per tick)
TIMEOUT_TICKS = 30  # 15 s
MAX_LINE = 65536    # longest accepted protocol line; longer input is dropped (DoS guard)
NAME_CHARS = "abcdefghijklmnopqrstuvwxyz0123456789_"
REF_CHARS = NAME_CHARS + ".+*-^@"


def log(tag, text):
    print("[" + tag + "] " + text)


def clean(s):
    # strip protocol delimiters from user data
    out = ""
    for ch in s:
        if ch in "|;,:~\n\r\t":
            continue
        out = out + ch
    return out


def valid(s, chars, maxlen):
    if len(s) == 0 or len(s) > maxlen:
        return False
    for ch in s:
        if ch not in chars:
            return False
    return True


def tokenize(text):
    # whitespace separates tokens; protocol delimiters and brackets are stripped
    # (so a user token can never be "<PAD>", the boundary token of the ingest)
    t0 = ""
    for ch in text:
        t0 = t0 + (" " if ch in "\t\r\n" else ch)
    toks = []
    for raw in t0.lower().split(" "):
        t = ""
        for ch in raw:
            if ch in ".!?\"'()[]{}<>|;,:~\n\r\t":
                continue
            t = t + ch
        if t != "":
            toks.append(t)
    return toks


# ---- SHA-1 on 16-bit halves: word = [lo, hi] ----
def _w(v):
    hi = v // 65536
    return [v - hi * 65536, hi]


def _add(a, b):
    lo = a[0] + b[0]
    c = lo // 65536
    hi = a[1] + b[1] + c
    return [lo - c * 65536, hi % 65536]


def _rotl(x, n):
    lo = x[0]
    hi = x[1]
    if n >= 16:
        lo, hi = hi, lo
        n = n - 16
    if n == 0:
        return [lo, hi]
    return [((lo << n) & 0xFFFF) | (hi >> (16 - n)), ((hi << n) & 0xFFFF) | (lo >> (16 - n))]


def sha1_hex(text):
    return sha1_bytes(utf8(text))


def sha1_bytes(data):
    # SHA-1 of a list of byte values -> 40 lowercase hex chars
    d = list(data)
    n = len(d)
    d.append(0x80)
    while len(d) % 64 != 56:
        d.append(0)
    bits = n * 8
    tail = []
    for i in range(8):
        q = bits // 256
        tail.append(bits - q * 256)
        bits = q
    for i in range(7, -1, -1):
        d.append(tail[i])
    h = [[0x2301, 0x6745], [0xab89, 0xefcd], [0xdcfe, 0x98ba], [0x5476, 0x1032], [0xe1f0, 0xc3d2]]
    K = [[0x7999, 0x5a82], [0xeba1, 0x6ed9], [0xbcdc, 0x8f1b], [0xc1d6, 0xca62]]
    for blk in range(0, len(d), 64):
        w = []
        for i in range(16):
            j = blk + i * 4
            w.append([(d[j + 2] << 8) | d[j + 3], (d[j] << 8) | d[j + 1]])
        for i in range(16, 80):
            x = [w[i - 3][0] ^ w[i - 8][0] ^ w[i - 14][0] ^ w[i - 16][0],
                 w[i - 3][1] ^ w[i - 8][1] ^ w[i - 14][1] ^ w[i - 16][1]]
            w.append(_rotl(x, 1))
        a = h[0]
        b = h[1]
        c = h[2]
        e4 = h[3]
        e = h[4]
        for i in range(80):
            if i < 20:
                f = [(b[0] & c[0]) | ((0xFFFF - b[0]) & e4[0]), (b[1] & c[1]) | ((0xFFFF - b[1]) & e4[1])]
                k = K[0]
            elif i < 40:
                f = [b[0] ^ c[0] ^ e4[0], b[1] ^ c[1] ^ e4[1]]
                k = K[1]
            elif i < 60:
                f = [(b[0] & c[0]) | (b[0] & e4[0]) | (c[0] & e4[0]),
                     (b[1] & c[1]) | (b[1] & e4[1]) | (c[1] & e4[1])]
                k = K[2]
            else:
                f = [b[0] ^ c[0] ^ e4[0], b[1] ^ c[1] ^ e4[1]]
                k = K[3]
            t = _add(_add(_add(_add(_rotl(a, 5), f), e), k), w[i])
            e = e4
            e4 = c
            c = _rotl(b, 30)
            b = a
            a = t
        h = [_add(h[0], a), _add(h[1], b), _add(h[2], c), _add(h[3], e4), _add(h[4], e)]
    digits = "0123456789abcdef"
    s = ""
    for wd in h:
        for v in (wd[1], wd[0]):
            for k in (12, 8, 4, 0):
                s = s + digits[(v >> k) & 15]
    return s


# ---- line-oriented connection helpers ----
class Line:
    """Wraps a PT TCPClient: buffers input, splits lines, dispatches."""

    def __init__(self, sock, on_line):
        self.sock = sock
        self.buf = ""
        self.on_line = on_line
        me = self

        def on_receive(data):          # PT calls plain functions only, not bound methods
            me._recv(data)
        sock.onReceive(on_receive)

    def _recv(self, data):
        self.buf = self.buf + data
        if len(self.buf) > MAX_LINE and "\n" not in self.buf:
            log("NET", "line too long, dropped " + str(len(self.buf)) + " chars")
            self.buf = ""
            return
        while "\n" in self.buf:
            i = self.buf.index("\n")
            line = self.buf[:i]
            self.buf = self.buf[i + 1:]
            if len(line) > MAX_LINE:
                log("NET", "line too long, dropped")
                continue
            if line != "":
                try:
                    self.on_line(self, line.split("|"))
                except Exception as e:
                    log("ERR", "handler: " + str(e))

    def send(self, fields):
        try:
            self.sock.send("|".join([str(f) for f in fields]) + "\n")
            return True
        except Exception as e:
            log("NET", "send failed: " + str(e))
            return False


class Server:
    """Listens on a port; handler(conn, rid, cmd, args) answers with conn.send([rid, ...])."""

    def __init__(self, name, port, handler):
        self.name = name
        self.port = port
        self.handler = handler
        self.srv = TCPServer()
        me = self

        def on_new_client(sock):       # PT calls plain functions only, not bound methods
            me._new(sock)
        self.srv.onNewClient(on_new_client)

    def start(self):
        self.srv.listen(self.port)
        log("NET", self.name + " listening on " + str(self.port))

    def _new(self, sock):
        Line(sock, self._line)

    def _line(self, conn, f):
        if len(f) < 2:
            return
        if f[1] == "HELLO":
            conn.send(["0", "WELCOME", self.name])
            return
        try:
            self.handler(conn, f[0], f[1], f[2:])
        except Exception as e:
            log("ERR", f[1] + ": " + str(e))
            conn.send([f[0], "ERR", clean(str(e))])


class Peer:
    """Outgoing connection with HELLO handshake, request ids and timeouts."""

    def __init__(self, name, ip, port):
        self.name = name
        self.ip = ip
        self.port = port
        self.ready = False
        self.conn = None
        self.tries = 0
        self.pending = {}
        self.next_id = [1]

    def _connect(self):
        if self.conn is not None:
            try:
                self.conn.sock.close()
            except Exception:
                pass
        sock = TCPClient()
        self.conn = Line(sock, self._line)
        sock.connect(self.ip, self.port)
        self.tries = 0

    def _line(self, conn, f):
        if len(f) >= 2 and f[0] == "0" and f[1] == "WELCOME":
            if not self.ready:
                log("NET", "connected to " + self.name + " " + self.ip + ":" + str(self.port))
            self.ready = True
            return
        rid = f[0]
        if rid in self.pending:
            cb = self.pending[rid][0]
            del self.pending[rid]
            cb(f[1:])

    def tick(self):
        if self.conn is None or (not self.ready and self.tries >= 20):
            self._connect()
        if not self.ready:
            self.tries = self.tries + 1
            self.conn.send(["0", "HELLO", self.name])
        dead = []
        for rid in self.pending:
            if TICK[0] - self.pending[rid][1] > TIMEOUT_TICKS:
                dead.append(rid)
        if len(dead) > 0 and self.ready:
            # the peer stopped answering: forget the session, reconnect + HELLO again
            log("NET", "lost " + self.name + ", reconnecting")
            self.ready = False
            self.tries = 20
        for rid in dead:
            cb = self.pending[rid][0]
            del self.pending[rid]
            cb(["ERR", "timeout " + self.name])

    def call(self, fields, cb):
        if not self.ready:
            cb(["ERR", self.name + " not connected"])
            return
        rid = "r" + str(self.next_id[0])
        self.next_id[0] = self.next_id[0] + 1
        self.pending[rid] = [cb, TICK[0]]
        if not self.conn.send([rid] + fields):
            del self.pending[rid]
            self.ready = False
            self.tries = 20
            cb(["ERR", self.name + " send failed"])


def run(tick_fn):
    while True:
        TICK[0] = TICK[0] + 1
        tick_fn()
        sleep(0.5)

# ---------------- HLLSet plane (hllset-core::HLLSet) as a set of bit positions ----------------
# bit = reg * 32 + tz  (0 .. 32767); plane = dict {bit: 1}
# Content key = "h:" + sha1(Roaring serialization), exactly like HLLSet::content_key()
# (roaring-rs 0.10, portable format without run containers).

ARRAY_LIMIT = 4096


def plane_from(s):
    p = {}
    if s == "" or s == "-":
        return p
    for x in s.split(","):
        b = int(x)
        if b < 0 or b >= 32768:
            raise Exception("bit out of range " + x)
        p[b] = 1
    return p


def plane_str(p):
    keys = sorted(p.keys())
    if len(keys) == 0:
        return "-"
    return ",".join([str(k) for k in keys])


def p_union(a, b):
    r = {}
    for k in a:
        r[k] = 1
    for k in b:
        r[k] = 1
    return r


def p_inter(a, b):
    r = {}
    for k in a:
        if k in b:
            r[k] = 1
    return r


def p_diff(a, b):
    r = {}
    for k in a:
        if k not in b:
            r[k] = 1
    return r


def p_xor(a, b):
    return p_union(p_diff(a, b), p_diff(b, a))


def p_hist(p):
    # HLLSet::bit_counts(): c_s = number of registers with bit s set (HT input, host side)
    c = [0] * 32
    for k in p:
        c[k % 32] = c[k % 32] + 1
    return c


def roaring_bytes(p):
    # RoaringBitmap::serialize_into: cookie 12346, container count, (key, card-1),
    # offsets, then the container. All bits < 32768 -> at most one container (key 0).
    keys = sorted(p.keys())
    n = len(keys)
    out = [0x3A, 0x30, 0, 0]
    if n == 0:
        return out + [0, 0, 0, 0]
    out = out + [1, 0, 0, 0, 0, 0, (n - 1) % 256, (n - 1) // 256, 16, 0, 0, 0]
    if n <= ARRAY_LIMIT:
        for k in keys:
            out.append(k % 256)
            out.append(k // 256)
        return out
    bm = [0] * 8192
    for k in keys:
        bm[k // 8] = bm[k // 8] | (1 << (k % 8))
    return out + bm


def cid_of(p):
    # HLLSet::content_key(): "h:" + sha1(roaring bytes)
    return "h:" + sha1_bytes(roaring_bytes(p))


def hexkey(t):
    # bytewise (UTF-8) sort key: Rust orders tokens as Vec<u8>; JS compares UTF-16 units
    digits = "0123456789abcdef"
    s = ""
    for b in utf8(t):
        s = s + digits[b >> 4] + digits[b & 15]
    return s


def sort_bytes(tokens):
    m = {}
    for t in tokens:
        m[hexkey(t)] = t
    return [m[k] for k in sorted(m.keys())]


# ---- wire encodings for LUT fibers and TF ----
def lut_str(lut):
    # lut = {bit: {token: 1}} -> "bit:tok;bit:tok"
    out = []
    for b in sorted(lut.keys()):
        for t in sort_bytes(lut[b].keys()):
            out.append(str(b) + ":" + t)
    return ";".join(out) if len(out) > 0 else "-"


def lut_from(s, into):
    if s == "" or s == "-":
        return into
    for e in s.split(";"):
        i = e.index(":")
        b = int(e[:i])
        fib = into.get(b)
        if fib is None:
            fib = {}
            into[b] = fib
        fib[e[i + 1:]] = 1
    return into


def tf_str(tf):
    out = []
    for t in sort_bytes(tf.keys()):
        out.append(t + ":" + str(tf[t]))
    return ";".join(out) if len(out) > 0 else "-"


def tf_from(s):
    tf = {}
    if s == "" or s == "-":
        return tf
    for e in s.split(";"):
        i = e.index(":")
        tf[e[:i]] = int(e[i + 1:])
    return tf

# ---------------- hllset-morphisms::api — default ingest / materialize ----------------
# Port of ewm-state-machine/crates/hllset-morphisms/src/api.rs:
#   padded = [PAD] + tokens + [PAD, PAD]
#   channel 0 (G1): 1-grams, seed 0     channel 1 (G2): 2-grams, seed 1
#   channel 2 (G3): 3-grams, seed 2     slide4 (S4_1d): 4-gram windows, seed 3, NO LUT
#   n-gram bytes = utf8 parts joined with a NUL byte.
#   LUT fiber of a window's bit holds the window's FIRST token, only for real start
#   positions 1..n (pad-leading windows only set the atom).
#   key = h:sha1(roaring(G1 | G2 | G3)); slide4 is not part of the projection.
# The swarm splits the window START positions [0, L) into ranges; every board ingests
# its range, the GRID unions the parts. Union is order-free, so the result is the same
# as one Rust ingest() call over the whole text.

PAD = "<PAD>"
CHANNEL_SEEDS = [0, 1, 2]
SLIDE_SEED = 3
CHANNEL_NAMES = ["G1", "G2", "G3"]
WALK_BUDGET = 20000     # node budget of the ordered walk (same as Rust)
BITCACHE = {}


def window_bit(parts, seed):
    key = str(seed) + " " + " ".join(parts)      # tokens never contain spaces
    b = BITCACHE.get(key)
    if b is not None:
        return b
    d = []
    for i in range(len(parts)):
        if i > 0:
            d.append(0)
        d = d + utf8(parts[i])
    b = bit_of_bytes(d, seed)
    if len(BITCACHE) > 20000:
        for k in list(BITCACHE.keys()):
            del BITCACHE[k]
    BITCACHE[key] = b
    return b


def ingest_part(toks, a, b, nreal):
    # toks = padded[a : min(b + 3, L)], window starts s in [a, b), L = nreal + 3
    L = nreal + 3
    g = [{}, {}, {}]
    s4 = {}
    luts = [{}, {}, {}]
    tf = {}
    for s in range(a, b):
        for n in range(1, 5):
            if s + n > L:
                continue
            w = toks[s - a: s - a + n]
            if n == 4:
                s4[window_bit(w, SLIDE_SEED)] = 1
                continue
            bit = window_bit(w, CHANNEL_SEEDS[n - 1])
            g[n - 1][bit] = 1
            if s >= 1 and s <= nreal:
                fib = luts[n - 1].get(bit)
                if fib is None:
                    fib = {}
                    luts[n - 1][bit] = fib
                fib[w[0]] = 1
        if s >= 1 and s <= nreal:
            t = toks[s - a]
            tf[t] = tf.get(t, 0) + 1
    return {"g": g, "s4": s4, "luts": luts, "tf": tf, "n": nreal}


def ingest_all(tokens):
    # the single-machine reference: one part covering every window
    padded = [PAD] + tokens + [PAD, PAD]
    return ingest_part(padded, 0, len(padded), len(tokens))


def seal(rec):
    # projection, keys and the hllsetLUT entries of a finished ingest
    proj = p_union(p_union(rec["g"][0], rec["g"][1]), rec["g"][2])
    rec["proj"] = proj
    rec["key"] = cid_of(proj)
    rec["keys"] = [cid_of(rec["g"][i]) for i in range(3)]
    return rec


def unordered_tokens(rec):
    # materialize_no_order: LUT-first over the three (sketch, LUT) pairs, keep every candidate
    out = {}
    for ch in range(3):
        for bit in rec["g"][ch]:
            fib = rec["luts"][ch].get(bit)
            if fib is not None:
                for t in fib:
                    out[t] = 1
    return sort_bytes(out.keys())


def _has(rec, ch, parts):
    return window_bit(parts, CHANNEL_SEEDS[ch]) in rec["g"][ch]


def _has4(rec, parts):
    return window_bit(parts, SLIDE_SEED) in rec["s4"]


def _edge_ok(rec, path, prev, cur, c):
    # the joint 2-/3-/4-gram edge check of walk() / beam_search()
    if not (_has(rec, 1, [cur, c]) and _has(rec, 2, [prev, cur, c])):
        return False
    if len(path) < 2:
        return True
    pp = PAD if len(path) == 2 else path[len(path) - 3]
    return _has4(rec, [pp, prev, cur, c])


def _rank(cands, tf):
    # TF descending, then bytewise ascending (Rust: b.tf.cmp(a.tf).then(a.cmp(b)))
    m = {}
    for t in cands:
        k = str(10000000 - tf.get(t, 0)) + "/" + hexkey(t)
        m[k] = t
    return [m[k] for k in sorted(m.keys())]


def materialize_ordered(rec):
    # api::materialize (Order::Ordered, beam 1): count-constrained greedy De Bruijn walk
    # with backtracking, anchored at the start pad. Iterative (no deep recursion on PT).
    tokens = unordered_tokens(rec)
    n = rec["n"]
    tf = rec["tf"]
    if len(tokens) == 0 or n == 0:
        return [], "empty"
    remaining = {}
    for t in tokens:
        if tf.get(t, 0) > 0:
            remaining[t] = tf[t]
    starts = _rank([t for t in tokens if remaining.get(t, 0) > 0 and _has(rec, 1, [PAD, t])], tf)
    budget = [WALK_BUDGET]
    for start in starts:
        if n == 1:
            return [start], "ordered"
        path = [start]
        rem = {}
        for t in remaining:
            rem[t] = remaining[t]
        rem[start] = rem[start] - 1
        if _walk(rec, tokens, path, rem, budget):
            return path, "ordered"
        if budget[0] == 0:
            break
    return tokens, "fallback-set"


def _enter(rec, tokens, path, rem, budget, prev, cur):
    # one call of Rust walk(): True / False, or a list of successors to try
    if budget[0] == 0:
        return False
    budget[0] = budget[0] - 1
    if len(path) == rec["n"]:
        return _edge_ok(rec, path, prev, cur, PAD)
    nexts = [c for c in tokens if rem.get(c, 0) > 0 and _edge_ok(rec, path, prev, cur, c)]
    return _rank(nexts, rec["tf"])


def _walk(rec, tokens, path, rem, budget):
    first = _enter(rec, tokens, path, rem, budget, PAD, path[0])
    if first is True or first is False:
        return first
    stack = [[PAD, path[0], first, 0]]          # frame = [prev, cur, nexts, next index]
    while len(stack) > 0:
        fr = stack[len(stack) - 1]
        if fr[3] >= len(fr[2]):
            stack.pop()                          # frame exhausted -> parent undoes its step
            if len(stack) == 0:
                return False
            last = path.pop()
            rem[last] = rem[last] + 1
            continue
        nx = fr[2][fr[3]]
        fr[3] = fr[3] + 1
        rem[nx] = rem[nx] - 1
        path.append(nx)
        r = _enter(rec, tokens, path, rem, budget, fr[1], nx)
        if r is True:
            return True
        if r is False:
            path.pop()
            rem[nx] = rem[nx] + 1
            continue
        stack.append([fr[1], nx, r, 0])
    return False


# ---- record wire format: g1|g2|g3|s4|lut1|lut2|lut3|tf ----
def rec_fields(rec):
    return [plane_str(rec["g"][0]), plane_str(rec["g"][1]), plane_str(rec["g"][2]), plane_str(rec["s4"]),
            lut_str(rec["luts"][0]), lut_str(rec["luts"][1]), lut_str(rec["luts"][2]), tf_str(rec["tf"])]


def rec_from(f, n):
    return {"g": [plane_from(f[0]), plane_from(f[1]), plane_from(f[2])], "s4": plane_from(f[3]),
            "luts": [lut_from(f[4], {}), lut_from(f[5], {}), lut_from(f[6], {})], "tf": tf_from(f[7]), "n": n}

# ================= FPGA board (swarm member): soldered HLLSet core =================
# Integer-only work: n-gram windows -> murmur3 -> (reg, tz) -> bit, LUT fibers, TF counts,
# lattice algebra OR/AND/AND-NOT/XOR, popcount, D/R/N, c_s histogram and the ordered
# materialize walk. Planes live in GRID (MERGE / SEAL / GET / PUT through the network).
BOARD = "FPGA5"
PORT = 5100
GRID_IP = "192.168.40.10"
GRID_PORT = 5200

GRID = Peer("GRID", GRID_IP, GRID_PORT)
STATS = {"windows": 0, "ops": 0}


def part(conn, rid, a):
    # PART|user|job|part|a|b|n|tok tok ...   window starts [a, b) of [PAD]+text+[PAD,PAD]
    user, job, pi, lo, hi, n = a[0], a[1], a[2], int(a[3]), int(a[4]), int(a[5])
    toks = a[6].split(" ")
    if lo < 0 or hi > n + 3 or lo >= hi or len(toks) != min(hi + 3, n + 3) - lo:
        conn.send([rid, "ERR", BOARD + ": bad part range"])
        return
    p = ingest_part(toks, lo, hi, n)
    STATS["windows"] = STATS["windows"] + (hi - lo)
    bits = len(p["g"][0]) + len(p["g"][1]) + len(p["g"][2])
    log("RED", BOARD + " PART " + user + " job " + job + "#" + pi + " windows " + str(lo) + ".." + str(hi - 1) + " -> " + str(bits) + " atoms")

    def done(r):
        if r[0] == "OK":
            conn.send([rid, "OK", BOARD, pi, hi - lo, bits])
        else:
            conn.send([rid, "ERR", BOARD + ": " + r[-1]])

    GRID.call(["MERGE", user, job, pi] + rec_fields(p), done)


def seal_req(conn, rid, a):
    # SEAL|user|job|name|n|parts
    def done(r):
        if r[0] == "OK":
            conn.send([rid, "OK", BOARD] + r[1:])
        else:
            conn.send([rid, "ERR", BOARD + ": " + r[-1]])
    GRID.call(["SEAL"] + a[:5], done)


def load2(user, ra, rb, cb):
    # fetch one or two planes from GRID, then cb(pa, pb) or cb(None, err)
    def got_a(r):
        if r[0] != "OK":
            cb(None, r[-1])
            return
        pa = plane_from(r[2])
        if rb is None:
            cb(pa, None)
            return

        def got_b(r2):
            if r2[0] != "OK":
                cb(None, r2[-1])
                return
            cb(pa, plane_from(r2[2]))

        GRID.call(["GET", user, rb], got_b)

    GRID.call(["GET", user, ra], got_a)


def query(conn, rid, a):
    # QUERY|user|OP|A|B
    user, op = a[0], a[1]
    ra = a[2] if len(a) > 2 else ""
    rb = a[3] if len(a) > 3 and a[3] != "" else None
    STATS["ops"] = STATS["ops"] + 1
    log("RED", BOARD + " " + op + " " + user + " " + ra + ("" if rb is None else " " + rb))

    def fail(msg):
        conn.send([rid, "ERR", BOARD + ": " + msg])

    def put_and_reply(name, p, extra):
        def ok(r):
            if r[0] == "OK":
                conn.send([rid, "OK", BOARD, name, r[1], r[2]] + extra)
            else:
                fail(r[-1])
        GRID.call(["PUT", user, name, plane_str(p)], ok)

    def compute(pa, pb):
        if pa is None:
            fail(pb)
            return
        if op == "INFO" or op == "POPCOUNT":
            conn.send([rid, "OK", BOARD, ra, cid_of(pa), len(pa)])
        elif op == "HIST":
            conn.send([rid, "OK", BOARD, ra, ",".join([str(c) for c in p_hist(pa)])])
        elif op == "UNION":
            put_and_reply(ra + "+" + rb, p_union(pa, pb), [])
        elif op == "INTERSECT":       # R-link: an HLLSet with its own CID
            put_and_reply(ra + "*" + rb, p_inter(pa, pb), [])
        elif op == "DIFF":
            put_and_reply(ra + "-" + rb, p_diff(pa, pb), [])
        elif op == "XOR":
            put_and_reply(ra + "^" + rb, p_xor(pa, pb), [])
        elif op == "SUBSET":
            conn.send([rid, "OK", BOARD, ra + "<=" + rb, "yes" if len(p_diff(pa, pb)) == 0 else "no"])
        elif op == "DRN":
            # A = H(t-1) previous state, B = S(t) current state (ewm-git view.rs)
            d = p_diff(pa, pb)
            r = p_inter(pa, pb)
            n = p_diff(pb, pa)
            res = []

            def step(i):
                parts = [["D." + ra + "." + rb, d], ["R." + ra + "." + rb, r], ["N." + ra + "." + rb, n]]
                if i == 3:
                    conn.send([rid, "OK", BOARD, "DRN"] + res)
                    return
                nm = parts[i][0]

                def ok(x):
                    if x[0] != "OK":
                        fail(x[-1])
                        return
                    res.append(nm[0] + "=" + str(x[2]) + "@" + x[1][:14])
                    step(i + 1)
                GRID.call(["PUT", user, nm, plane_str(parts[i][1])], ok)
            step(0)
        elif op == "LOOKUP":
            def got(r):
                if r[0] == "OK":
                    conn.send([rid, "OK", BOARD, ra, r[1], r[2], "set"])
                else:
                    fail(r[-1])
            GRID.call(["LOOKUP", user, plane_str(pa)], got)
        else:
            fail("unknown op " + op)

    if op == "LIST" or op == "STAT" or op == "HLUT":
        def got_list(r):
            conn.send([rid] + r[:1] + [BOARD] + r[1:])
        GRID.call([op, user], got_list)
        return
    if op == "LOOKUP" or op == "TOKENS":
        # an ingest record is restored by hllset-morphisms::materialize (ordered) or
        # materialize_no_order; a computed node falls back to the LUT-first set
        def got_rec(r):
            if r[0] == "NOREC":
                load2(user, ra, None, compute)
                return
            if r[0] != "OK":
                fail(r[-1])
                return
            rec = rec_from(r[3:11], int(r[2]))
            if op == "TOKENS":
                toks = unordered_tokens(rec)
                mode = "no_order"
            else:
                res = materialize_ordered(rec)
                toks = res[0]
                mode = res[1]
            conn.send([rid, "OK", BOARD, ra, len(toks), " ".join(toks) if len(toks) > 0 else "-", mode])
        GRID.call(["REC", user, ra], got_rec)
        return
    two = op in ["UNION", "INTERSECT", "DIFF", "XOR", "SUBSET", "DRN"]
    if two and rb is None:
        fail(op + " needs two sets")
        return
    load2(user, ra, rb if two else None, compute)


def handle(conn, rid, cmd, a):
    if cmd == "PART":
        part(conn, rid, a)
    elif cmd == "SEAL":
        seal_req(conn, rid, a)
    elif cmd == "QUERY":
        query(conn, rid, a)
    elif cmd == "PING":
        conn.send([rid, "OK", BOARD, "grid=" + ("up" if GRID.ready else "down")])
    else:
        conn.send([rid, "ERR", "unknown " + cmd])


SERVER = Server(BOARD, PORT, handle)


def tick():
    GRID.tick()
    if TICK[0] % 120 == 0:
        log(BOARD, "windows=" + str(STATS["windows"]) + " ops=" + str(STATS["ops"]) + " grid=" + ("up" if GRID.ready else "down"))


def main():
    log(BOARD, "board starting")
    SERVER.start()
    run(tick)


if __name__ == "__main__":
    main()
